-- =====================================================================
-- Hofmanager SchweikFarm – Import: Ackerflächen und Fruchtfolge 2023–2029
-- Quelle: Fruchtfolgerapport/Parzellenregister (Excel, Blatt «Anpassung 26»)
-- Einspielen: Supabase › SQL Editor › gesamten Inhalt einfügen › Run (Migrationen 7 und 8 müssen eingespielt sein)
-- Bestehende Felder mit gleichem Namen werden aktualisiert, Anbau-Einträge je Jahr überschrieben.
-- Saat-/Erntemonat stammen aus dem Monatsraster und sind als «nur Monat» markiert.
-- =====================================================================
do $$
declare
  v_betrieb uuid := (select id from public.betriebe order by erstellt_am limit 1);
  v_feld uuid;
  v_nr text;
begin
  if v_betrieb is null then raise exception 'Zuerst in der App den Betrieb einrichten'; end if;
  if not exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'anbau_hauptkultur') then
    raise exception 'Zuerst Migration 8 (Papierkorb, mehrere Kulturen) einspielen';
  end if;
  -- 9 Obere Suterweid (0.8 ha)
  select id into v_feld from public.felder where betrieb_id = v_betrieb and lower(name) = lower('Obere Suterweid') and geloescht_am is null limit 1;
  if v_feld is null then
    v_nr := '9';
    while exists (select 1 from public.felder where betrieb_id = v_betrieb and feldnummer = v_nr) loop v_nr := v_nr || 'x'; end loop;
    insert into public.felder (betrieb_id, feldnummer, name, flaeche_m2, nutzungsart, korrektur_p2o5, korrektur_k2o, korrektur_mg, bemerkungen)
    values (v_betrieb, v_nr, 'Obere Suterweid', 8000.0, 'Ackerland', 1.1, 1.0, 0.0, 'Importiert aus Fruchtfolgerapport 2023–2029') returning id into v_feld;
  else
    update public.felder set flaeche_m2 = 8000.0, korrektur_p2o5 = 1.1, korrektur_k2o = 1.0, korrektur_mg = 0.0 where id = v_feld;
  end if;
  insert into public.anbau (betrieb_id, feld_id, kultur_id, jahr, art, status, saatdatum, erntedatum, nur_monat, bemerkungen) select v_betrieb, v_feld, id, 2022, 'Zwischenkultur', 'ist', null::date, '2023-03-01'::date, true, 'Fruchtfolgerapport' from public.kulturen where betrieb_id is null and name = 'Gründüngung' on conflict (feld_id, jahr, art, kultur_id) do update set status = excluded.status, saatdatum = excluded.saatdatum, erntedatum = excluded.erntedatum, nur_monat = true;
  insert into public.anbau (betrieb_id, feld_id, kultur_id, jahr, art, status, saatdatum, erntedatum, nur_monat, bemerkungen) select v_betrieb, v_feld, id, 2023, 'Hauptkultur', 'ist', '2023-03-01'::date, '2023-09-01'::date, true, 'Fruchtfolgerapport' from public.kulturen where betrieb_id is null and name = 'Sommerweizen' on conflict (feld_id, jahr) where art = 'Hauptkultur' do update set kultur_id = excluded.kultur_id, status = excluded.status, saatdatum = excluded.saatdatum, erntedatum = excluded.erntedatum, nur_monat = true;
