-- Kontrolle: Felder und Anbau 2026
select f.feldnummer, f.name, f.flaeche_m2 / 10000 as ha, k.name as kultur_2026 from public.felder f
left join public.anbau a on a.feld_id = f.id and a.jahr = 2026 and a.art = 'Hauptkultur'
left join public.kulturen k on k.id = a.kultur_id order by f.feldnummer;
